import { RandomImpl } from "#base/scripts/random-pcg-32.js";
import { ParameterSpec } from "#base/scripts/voronoi-types.js";
import { VoronoiUtils } from "#base/scripts/voronoi-utils.js";
import {
	ContinentGenerator,
	continentGeneratorRulesSettings,
	continentGeneratorSchema,
	ContinentGeneratorSettings,
} from "#base/scripts/voronoi_generators/continent-generator.js";
import {
	MapBaseSettings,
	MapSettingSchema,
	VoronoiMap,
	voronoiMapSchema,
} from "#base/scripts/voronoi_maps/map-common.js";

export interface UnifiedContinentsBaseSettings extends MapBaseSettings {
	totalLandmassSize: number;
	maxSizeVariance: number;
	landmassCount: number;
	landmassGroupCount: number;
	totalDistantSize: number;
	maxDistantSizeVariance: number;
	distantCount: number;
	groupBalancedMode: number;
	minPlayersPerLandmassGroup: number;
	minLandmassSpawnCenterDistance: number;
	maxLandmassSpawnCenterDistance: number;
	minDistantSpawnCenterDistance: number;
	maxDistantSpawnCenterDistance: number;
	enforceGroupConstraints: number;
}

export const unifiedContinentsSchema = {
	...voronoiMapSchema,
	totalLandmassSize: {
		label: "Total Landmass Size",
		description: "The total percentage of land to be taken up by the major landmasses.",
		default: 32,
		min: 20,
		max: 50,
		step: 0.25,
	},
	maxSizeVariance: {
		label: "Max Size Variance",
		description:
			"The maximum difference allowed for between the largest and smallest continents as a percentage. For instance, 50% would mean the smallest landmass can be half the size of the largest.",
		default: 20,
		min: 0,
		max: 50,
		step: 1,
	},
	landmassCount: {
		label: "Landmass Count",
		description: "The number of major landmasses to spawn.",
		default: 4,
		min: 0,
		max: 20,
		step: 1,
	},
	landmassGroupCount: {
		label: "Landmass Group Count",
		description:
			"The number of groups to divide landmasses into. Landmasses in the same group are more likely to be closer together and less likely to have ocean between them.",
		default: 1,
		min: 1,
		max: 10,
		step: 1,
	},
	totalDistantSize: {
		label: "Total Distant Size",
		description: 'The total percentage of land to be taken up by the "distant" landmasses.',
		default: 4,
		min: 0,
		max: 20,
		step: 0.25,
	},
	maxDistantSizeVariance: {
		label: "Max Distant Size Variance",
		description:
			'The maximum difference allowed for between the largest and smallest "distant" landmasses as a percentage. For instance, 50% would mean the smallest landmass can be half the size of the largest.',
		default: 20,
		min: 0,
		max: 50,
		step: 1,
	},
	distantCount: {
		label: "Distant Land Count",
		description: "The number of primary distant landmasses to spawn.",
		default: 0,
		min: 0,
		max: 10,
		step: 1,
	},
	groupBalancedMode: {
		label: "Balance Landmass Groups",
		description: "0: evenly space groups, 1: slightly randomize, 2: fully random.",
		default: 0,
		min: 0,
		max: 2,
		step: 1,
		hidden: true,
	},
	minPlayersPerLandmassGroup: {
		label: "Min Players per Landmass Group",
		description:
			"The minimum number of players that should spawn on each landmass group. This is used to help ensure that each landmass group is large enough to host at least a certain number of players, which can help prevent very small landmasses that only host one player.",
		default: 2,
		min: 0,
		max: 4,
		step: 1,
		hidden: true,
	},
	minLandmassSpawnCenterDistance: {
		label: "Min Landmass Spawn Center Distance",
		description: "The minimum distance ratio from the center of the map that a landmass can spawn.",
		default: 0.3,
		min: 0,
		max: 1,
		step: 0.05,
		hidden: true,
	},
	maxLandmassSpawnCenterDistance: {
		label: "Max Landmass Spawn Center Distance",
		description: "The maximum distance ratio from the center of the map that a landmass can spawn.",
		default: 0.8,
		min: 0,
		max: 1,
		step: 0.05,
		hidden: true,
	},
	minDistantSpawnCenterDistance: {
		label: "Min Distant Landmass Spawn Center Distance",
		description: "The minimum distance ratio from the center of the map that a distant landmass can spawn.",
		default: 0.4,
		min: 0,
		max: 1,
		step: 0.05,
		hidden: true,
	},
	maxDistantSpawnCenterDistance: {
		label: "Max Distant Landmass Spawn Center Distance",
		description: "The maximum distance ratio from the center of the map that a distant landmass can spawn.",
		default: 0.6,
		min: 0,
		max: 1,
		step: 0.05,
		hidden: true,
	},
	enforceGroupConstraints: {
		label: "Enforce Group Constraints",
		description:
			"When enabled, iteratively refines landmass positions to keep same-group landmasses close together and separated from other groups.",
		default: 0,
		min: 0,
		max: 1,
		step: 1,
		hidden: true,
	},
};

export abstract class UnifiedContinentsBase<
	T extends UnifiedContinentsBaseSettings = UnifiedContinentsBaseSettings,
> extends VoronoiMap<T> {
	constructor(customSchema?: MapSettingSchema, defaultMapSettings?: object) {
		// Lock the landmass sizes so they can't be edited in the UI or saved since they are driven by the map type.
		const schema = VoronoiUtils.clone(continentGeneratorSchema);
		// Lock the landmass sizes so they can't be edited in the UI or saved since they are driven by the map type.
		(schema.landmass.children.data.size as ParameterSpec).locked = true;
		(schema.landmass.children.data.variance as ParameterSpec).locked = true;

		// unify some landmass settings to expose as single properties for the whole array of landmasses.
		(schema.landmass.children.data.erosionPercent as ParameterSpec).unified = true;
		(schema.landmass.children.data.erosionRandomness as ParameterSpec).unified = true;
		(schema.landmass.children.data.erosionTime as ParameterSpec).unified = true;

		(schema.landmass.children.data.coastalIslands as ParameterSpec).unified = true;
		(schema.landmass.children.data.coastalIslandsMinDistance as ParameterSpec).unified = true;
		(schema.landmass.children.data.coastalIslandsMaxDistance as ParameterSpec).unified = true;
		(schema.landmass.children.data.coastalIslandsSize as ParameterSpec).unified = true;
		(schema.landmass.children.data.coastalIslandsSizeVariance as ParameterSpec).unified = true;

		const generator = new ContinentGenerator(schema, { ...continentGeneratorRulesSettings });

		super(
			{ ...unifiedContinentsSchema, ...customSchema },
			generator,
			generator.getDefaultGeneratorSettings(),
			generator.getDefaultRuleSettings(),
			defaultMapSettings,
		);
	}

	override simulateInternal() {
		this.applySettings();
	}

	applySettings() {
		const hexDims = this.m_hexDims;
		const generatorSettings = this.getGenerator().getSettings() as ContinentGeneratorSettings;
		const landmassCount = this.m_settings.landmassCount;
		const distantCount = this.m_settings.distantCount;
		const groupCount = Math.min(this.m_settings.landmassGroupCount, landmassCount);
		const totalLandmassCount = landmassCount + distantCount;
		generatorSettings.landmass = Array.from({ length: totalLandmassCount }, () => ({
			...generatorSettings.landmass[0],
		}));

		// Adjust the total and min size slightly based on the amount of area likely to be taken up by landmass boundaries
		// This helps maintain consistency between map sizes since the oceans need to take up a larger percentage of smaller maps
		// to ensure landmasses are separated by ocean tiles.

		const tileCount = hexDims.x * hexDims.y;
		const avgDim = (hexDims.x + hexDims.y) / 2;
		const landmassSeparationWidth = 2;

		// total number of tiles expected to be lost to ensuring landmass separation
		const separationAxis = 2 * Math.sqrt(totalLandmassCount) - 2; // estimate number of axis of separation for n landmasses.
		const landmassSeparationTiles = avgDim * separationAxis * landmassSeparationWidth;
		const usablePercentage = (tileCount - landmassSeparationTiles) / tileCount;

		const calculateSizes = (count: number, totalSize: number, maxSizeVariance: number) => {
			const maxSizeVarianceComp = 1 - maxSizeVariance;

			// Calculates min and max sizes by taking the total usable percentage and dividing it up by 1 max size landmass, 1
			// min size landmass, and n remaining landmasses that are an average of the first two).
			const maxSize = totalSize / (1 + maxSizeVarianceComp + Math.max(0, count - 2) * (1 - maxSizeVariance / 2));
			const minSize = maxSize * maxSizeVarianceComp;

			return [minSize, maxSize];
		};

		const adjustedTotalSize = this.m_settings.totalLandmassSize * usablePercentage;
		const [minSize, maxSize] = calculateSizes(
			landmassCount,
			adjustedTotalSize,
			this.getSettings().maxSizeVariance * 0.01,
		);
		const landmassSizes = VoronoiUtils.distributeTotal(adjustedTotalSize, minSize, maxSize, landmassCount);

		const adjustedTotalDistantSize = this.m_settings.totalDistantSize * usablePercentage;
		const [minDistantSize, maxDistantSize] = calculateSizes(
			distantCount,
			adjustedTotalDistantSize,
			this.getSettings().maxDistantSizeVariance * 0.01,
		);
		const distantSizes = VoronoiUtils.distributeTotal(
			adjustedTotalDistantSize,
			minDistantSize,
			maxDistantSize,
			distantCount,
		);

		const getDistantDistance = (rand: number) =>
			VoronoiUtils.lerp(
				this.m_settings.minDistantSpawnCenterDistance,
				this.m_settings.maxDistantSpawnCenterDistance,
				rand,
			);
		const getLandmassDistance = (rand: number) =>
			VoronoiUtils.lerp(
				this.m_settings.minLandmassSpawnCenterDistance,
				this.m_settings.maxLandmassSpawnCenterDistance,
				rand,
			);

		// --- Step 1: Build the interleaved ordering ---
		// Create groups for landmasses to control how they are spaced. The landmasses for each group are placed
		// contiguously, and the distant landmasses are distributed as evenly as possible among the groups to space
		// them out. If there are fewer distant landmasses than groups, the distant landmasses will only be placed
		// in between groups, otherwise they will also be placed within groups.

		const landmassGroups: number[] = Array<number>(totalLandmassCount).fill(0);
		let remainingLandmasses = landmassCount;

		let writeIndex = 0;
		let remainingMidGroupDistant = Math.min(distantCount, groupCount);
		const extraDistant = Math.max(0, distantCount - groupCount);
		const minGroupSize = Math.floor(landmassCount / groupCount);
		let extraAccumulator =
			landmassCount > 0
				? RandomImpl.getRandomNumber(minGroupSize * 0.25, "Distant Lands Extra Spacing Offset") +
					minGroupSize * 0.5
				: 0;

		for (let groupId = 0; groupId < groupCount; ++groupId) {
			const gapsBeforeGroup = Math.round(remainingMidGroupDistant / (groupCount - groupId));
			writeIndex += gapsBeforeGroup;
			remainingMidGroupDistant -= gapsBeforeGroup;

			const landmassesInGroup = Math.round(remainingLandmasses / (groupCount - groupId));

			for (let i = 0; i < landmassesInGroup; ++i) {
				extraAccumulator += extraDistant;
				while (landmassCount > 0 && extraAccumulator > landmassCount) {
					writeIndex++;
					extraAccumulator -= landmassCount;
				}
				landmassGroups[writeIndex % totalLandmassCount] = groupId + 1;
				writeIndex++;
			}
			remainingLandmasses -= landmassesInGroup;
		}

		if (this.m_settings.groupBalancedMode == 1) {
			for (let i = 0; i < landmassGroups.length - 1; ++i) {
				if (RandomImpl.getRandomNumber(2, "Distant Lands Slight Random") > 0) {
					[landmassGroups[i], landmassGroups[i + 1]] = [landmassGroups[i + 1], landmassGroups[i]];
				}
			}
		} else if (this.m_settings.groupBalancedMode == 2) {
			VoronoiUtils.shuffle(landmassGroups);
		}

		// --- Step 2: Place all landmasses around a circle with proportional angular slices ---
		// Each slot gets angular room proportional to its land weight so larger landmasses aren't cramped.
		const singleGroupCenter = groupCount === 1;
		let landmassIdx = 0;
		let distantIdx = 0;

		// Build slot sizes/weights: for each slot, pick the next distant or landmass size.
		const slotWeights: number[] = [];
		for (let i = 0; i < totalLandmassCount; ++i) {
			if (landmassGroups[i] === 0) {
				slotWeights.push(distantSizes[distantIdx++]);
			} else {
				slotWeights.push(landmassSizes[landmassIdx++]);
			}
		}

		const totalSlotWeight = slotWeights.reduce((a, b) => a + b, 0);
		const randSpawnOffset = Math.PI * 2.0 * RandomImpl.fRand("Landmass spawn offset");
		const rands: number[] = VoronoiUtils.getPoissonRands(totalLandmassCount, "Landmass Spawn Distance");

		const positions: float2[] = [];
		let cumulativeAngle = randSpawnOffset;

		for (let i = 0; i < totalLandmassCount; ++i) {
			const sliceAngle =
				totalSlotWeight > 0
					? (slotWeights[i] / totalSlotWeight) * (2 * Math.PI)
					: (2 * Math.PI) / totalLandmassCount;

			const angle = cumulativeAngle + sliceAngle * 0.5;
			const distFn = landmassGroups[i] === 0 ? getDistantDistance : getLandmassDistance;
			const distance = VoronoiUtils.clamp(distFn(rands[i]), 0, 1) * 0.5;
			positions.push({ x: 0.5 + Math.cos(angle) * distance, y: 0.5 + Math.sin(angle) * distance });
			cumulativeAngle += sliceAngle;
		}

		// In single-group mode, pin the first player landmass near the map center.
		// This serves as the group's anchor so the cluster forms around it.
		let pinnedCenter = -1;
		const pinnedPos: float2 = { x: 0.5, y: 0.5 };
		if (singleGroupCenter) {
			for (let i = 0; i < totalLandmassCount; ++i) {
				if (landmassGroups[i] > 0) {
					pinnedCenter = i;
					// Place near center with a small random offset.
					const offsetAngle = RandomImpl.fRand("Pinned center angle") * Math.PI * 2;
					const offsetDist = Math.sqrt(RandomImpl.fRand("Pinned center dist")) * 0.05;
					pinnedPos.x = 0.5 + Math.cos(offsetAngle) * offsetDist;
					pinnedPos.y = 0.5 + Math.sin(offsetAngle) * offsetDist;
					positions[i].x = pinnedPos.x;
					positions[i].y = pinnedPos.y;
					break;
				}
			}
		}

		// --- Step 3: Iterative constraint refinement (optional) ---
		// When enabled, refines positions via push/pull constraints derived from their sizes:
		//   - Pull same-group landmasses together when too far apart
		//   - Push ALL landmasses apart when too close
		//   - Prefer group neighbors over non-group neighbors
		if (this.m_settings.enforceGroupConstraints) {
			// Convert positions from normalized [0,1] to hex-dims space so all distance
			// calculations are based on the actual map size. We convert back to normalized
			// space when writing the final seed locations.
			const W = hexDims.x;
			const H = hexDims.y;
			for (let i = 0; i < totalLandmassCount; ++i) {
				positions[i].x *= W;
				positions[i].y *= H;
			}
			// Also convert the pinned center position if applicable.
			pinnedPos.x *= W;
			pinnedPos.y *= H;

			// Slot sizes = slot weights + coastal island size for each landmass.
			const slotSizes = slotWeights.map((w, i) => w + (generatorSettings.landmass[i].coastalIslandsSize ?? 0));

			// Derive minimum distance between two landmasses from their combined size.
			// In hex-dims space the map has area W*H tiles. A landmass covering S% of
			// the map occupies S/100 * W*H tiles, giving radius = sqrt(S/100 * W*H / PI).

			const sameGroupPadding = 1.0; // same group typically is separated by 1 tile of ocean/coast.
			const sameGroupMultiplier = 0.75; // same-group landmasses can be slightly closer together since they're typically not perfect circles.
			const diffGroupPadding = 4.0; // different groups are typically separated by 2 coast and at least 2 ocean tiles.
			const diffGroupMultiplier = 1.25; // different-group landmasses should be farther apart to avoid accidental bridging.
			const radiusOf = (size: number) => Math.sqrt(((size / 100) * W * H) / Math.PI);

			const minDistBetween = (sizeA: number, sizeB: number, sameGroup: boolean) => {
				const padding = sameGroup ? sameGroupPadding : diffGroupPadding;
				const multiplier = sameGroup ? sameGroupMultiplier : diffGroupMultiplier;
				return (radiusOf(sizeA) + radiusOf(sizeB)) * multiplier + padding;
			};

			// Max distance between two same-group landmasses before pulling them together.
			const groupDistMultiplier = 1.0;
			const maxGroupDistBetween = (sizeA: number, sizeB: number) => {
				return (radiusOf(sizeA) + radiusOf(sizeB)) * groupDistMultiplier + sameGroupPadding;
			};
			const constraintIterations = 50;
			const mstStrength = 0.8; // MST pulls together more strongly than the separation force pushes apart to maintain group cohesion.
			const separationStrength = 0.3;

			// Build MST for each player group (once, before iteration loop)
			const groupMembers = new Map<number, number[]>();
			for (let i = 0; i < totalLandmassCount; ++i) {
				const gid = landmassGroups[i];
				if (gid === 0) continue;
				if (!groupMembers.has(gid)) groupMembers.set(gid, []);
				groupMembers.get(gid)!.push(i);
			}

			// MST Algorithm summary: starting from an arbitrary landmass in the group (0), repeatedly find the closest pair of landmasses
			// where one is already in the tree and the other is not, and add that edge to the tree until all landmasses are included.
			const groupMSTs = new Map<number, [number, number][]>();
			for (const [gid, members] of groupMembers) {
				if (members.length < 2) continue;

				const inTree = new Set<number>();
				const mstEdges: [number, number][] = [];
				inTree.add(members[0]);

				while (inTree.size < members.length) {
					let bestDist = Infinity;
					let bestFrom = -1;
					let bestTo = -1;

					for (const from of inTree) {
						for (const to of members) {
							if (inTree.has(to)) continue;
							const dx = positions[to].x - positions[from].x;
							const dy = positions[to].y - positions[from].y;
							const d = Math.sqrt(dx * dx + dy * dy);
							if (d < bestDist) {
								bestDist = d;
								bestFrom = from;
								bestTo = to;
							}
						}
					}

					if (bestTo >= 0) {
						inTree.add(bestTo);
						mstEdges.push([bestFrom, bestTo]);
					} else {
						break;
					}
				}

				groupMSTs.set(gid, mstEdges);
			}

			const convergenceThreshold = 0.2; // converge when no position moves more than 0.2 tiles

			// Applies a displacement between two positions along their connecting axis.
			// Positive `amount` pushes apart, negative pulls together.
			// When massA/massB are provided, displacement is mass-weighted; otherwise symmetric.
			const applyForce = (pa: float2, pb: float2, dist: number, amount: number, massA = 1, massB = 1) => {
				let nx: number;
				let ny: number;
				if (dist > 0) {
					nx = (pb.x - pa.x) / dist;
					ny = (pb.y - pa.y) / dist;
				} else {
					// Derive a pseudo-random angle from the positions. This edge case should almost never happen.
					const angle = ((pa.x * 7 + pa.y * 13 + pb.x * 17 + pb.y * 23) % 360) * (Math.PI / 180);
					nx = Math.cos(angle);
					ny = Math.sin(angle);
				}
				const totalMass = massA + massB;
				const ratioA = totalMass > 0 ? massB / totalMass : 0.5;
				const ratioB = totalMass > 0 ? massA / totalMass : 0.5;
				pa.x -= nx * amount * ratioA;
				pa.y -= ny * amount * ratioA;
				pb.x += nx * amount * ratioB;
				pb.y += ny * amount * ratioB;
			};

			for (let iter = 0; iter < constraintIterations; ++iter) {
				// Snapshot positions to measure actual movement for convergence.
				const prevPositions = positions.map((p) => ({ x: p.x, y: p.y }));

				// Reduce correction magnitudes over iterations to prevent ping-pong.
				const damping = 1 - 0.5 * (iter / constraintIterations);
				const currentMST = mstStrength * damping;
				const currentSep = separationStrength * damping;

				// Pass 1: MST edge constraints - Both pull AND push on MST edges to maintain ideal intra-group spacing.
				for (const [gid, members] of groupMembers) {
					const mstEdges = groupMSTs.get(gid);
					if (!mstEdges || members.length < 2) continue;

					for (const [a, b] of mstEdges) {
						const pa = positions[a];
						const pb = positions[b];
						const dx = pb.x - pa.x;
						const dy = pb.y - pa.y;
						const dist = Math.sqrt(dx * dx + dy * dy);
						const maxDist = maxGroupDistBetween(slotSizes[a], slotSizes[b]);
						const minDist = minDistBetween(slotSizes[a], slotSizes[b], true);

						if (dist > maxDist) {
							applyForce(pa, pb, dist, -(dist - maxDist) * currentMST);
						} else if (dist < minDist) {
							applyForce(pa, pb, dist, (minDist - dist) * currentMST);
						}
					}
				}

				// Pass 2: Cross-group separation - Only push apart pairs from different groups (or involving distant lands).
				for (let i = 0; i < totalLandmassCount; ++i) {
					for (let j = i + 1; j < totalLandmassCount; ++j) {
						if (landmassGroups[i] > 0 && landmassGroups[i] === landmassGroups[j]) continue;

						const pi = positions[i];
						const pj = positions[j];
						const dx = pj.x - pi.x;
						const dy = pj.y - pi.y;
						const dist = Math.sqrt(dx * dx + dy * dy);
						const minDist = minDistBetween(slotSizes[i], slotSizes[j], false);

						if (dist < minDist) {
							const amount = (minDist - (dist > 0 ? dist : 0)) * currentSep;
							applyForce(pi, pj, dist, amount, slotSizes[i], slotSizes[j]);
						}
					}
				}

				// Map edge constraint + convergence check.
				let maxMovementSq = 0;
				const edgePadding = 2; // minimum distance from edge in tiles
				for (let i = 0; i < totalLandmassCount; ++i) {
					const r = radiusOf(slotSizes[i]);
					const loX = Math.max(edgePadding, r);
					const hiX = Math.min(W - edgePadding, W - r);
					const loY = Math.max(edgePadding, r);
					const hiY = Math.min(H - edgePadding, H - r);

					positions[i].x = VoronoiUtils.clamp(positions[i].x, loX, hiX);
					positions[i].y = VoronoiUtils.clamp(positions[i].y, loY, hiY);

					// In single-group mode, hard-pin the center landmass.
					if (singleGroupCenter && i === pinnedCenter) {
						positions[i].x = pinnedPos.x;
						positions[i].y = pinnedPos.y;
					}

					const dx = positions[i].x - prevPositions[i].x;
					const dy = positions[i].y - prevPositions[i].y;
					maxMovementSq = Math.max(maxMovementSq, dx * dx + dy * dy);
				}

				if (maxMovementSq < convergenceThreshold * convergenceThreshold) break;
			}

			// Convert positions back from hex-dims space to normalized [0,1].
			for (let i = 0; i < totalLandmassCount; ++i) {
				positions[i].x /= W;
				positions[i].y /= H;
			}
		}

		// --- Step 4: Assign the final positions, sizes, and groups ---
		landmassIdx = 0;
		distantIdx = 0;

		for (let i = 0; i < totalLandmassCount; ++i) {
			const landmass = generatorSettings.landmass[i];
			if (landmassGroups[i] === 0) {
				landmass.size = distantSizes[distantIdx++];
				landmass.playerAreas = 0;
			} else {
				landmass.size = landmassSizes[landmassIdx++];
				landmass.playerAreas = 1;
			}
			landmass.xPos = positions[i].x;
			landmass.yPos = positions[i].y;
			landmass.variance = 0;
			landmass.groupId = landmassGroups[i];
		}
	}

	getSettingsConfig(): MapSettingSchema {
		return this.m_baseSchema;
	}
}
